export const ashramData=[{id:"parmarth",name:"Parmarth Niketan",location:"Rishikesh",state:"Uttarakhand",tradition:"Yoga and Meditation",image:"assets/ashrams/parmarth.jpg",description:"One of the largest ashrams in Rishikesh, famous for its daily Ganga Aarti and the International Yoga Festival."},{id:"sivananda",name:"Sivananda Ashram",location:"Rishikesh",state:"Uttarakhand",tradition:"Vedanta and Yoga",image:"assets/ashrams/sivananda.jpg",description:"Founded by Swami Sivananda, this ashram is the headquarters of the Divine Life Society, focusing on the synthesis of all yogas."},{id:"isha",name:"Isha Yoga Center",location:"Coimbatore",state:"Tamil Nadu",tradition:"Isha Yoga (Sadhguru)",image:"assets/ashrams/isha.jpg",description:"A sacred space for self-transformation situated at the foothills of the Velliangiri Mountains, housing the Dhyanalinga."},{id:"bihar",name:"Bihar School of Yoga",location:"Munger",state:"Bihar",tradition:"Satyananda Yoga",image:"assets/ashrams/bihar.jpg",description:"An institution of yogic studies integrating traditional Vedanta and Tantra with modern physical and mental sciences."},{id:"auroville",name:"Auroville",location:"Near Puducherry",state:"Tamil Nadu",tradition:"Integral Yoga (Sri Aurobindo)",image:"assets/ashrams/auroville.jpg",description:"An experimental, universal township dedicated to the ideal of human unity and the practice of Integral Yoga."}];export const eightLimbs=[{name:"Yama",meaning:"Ethical Standards",description:"Universal morality and ethical disciplines, focusing on our behavior and how we conduct ourselves in life."},{name:"Niyama",meaning:"Self-Discipline",description:"Personal observances, spiritual practices, and self-discipline, such as attending temple or church services regularly, saying grace before meals, developing your own personal meditation practices."},{name:"Asana",meaning:"Physical Postures",description:"The physical postures practiced in yoga, designed to purify the body and provide the physical strength and stamina required for long periods of meditation."},{name:"Pranayama",meaning:"Breath Control",description:"Techniques designed to gain mastery over the respiratory process while recognizing the connection between the breath, the mind, and the emotions."},{name:"Pratyahara",meaning:"Sensory Withdrawal",description:"The conscious effort to draw our awareness away from the external world and outside stimuli, directing our attention internally."},{name:"Dharana",meaning:"Concentration",description:"The practice of intense concentration, bringing the mind to a single point of focus, often an object, a mantra, or the breath."},{name:"Dhyana",meaning:"Meditation",description:"An uninterrupted flow of concentration; a state of keen awareness without focus, where the mind is quiet and still."},{name:"Samadhi",meaning:"State of Ecstasy",description:"A state of profound connection to the Divine, an interconnectedness with all living things, and a state of complete peace."}];